import{_ as o,o as i,c as t,a4 as a}from"./chunks/framework.DpgogGqy.js";const g=JSON.parse('{"title":"Pipeline Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md"}'),n={name:"guide/overview.md"};function l(r,e,s,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="pipeline-overview" tabindex="-1">Pipeline Overview <a class="header-anchor" href="#pipeline-overview" aria-label="Permalink to &quot;Pipeline Overview&quot;">​</a></h1><p>Supernova is a multi-framework component pipeline bridging design systems in Figma directly to production component libraries across multiple frontend frameworks.</p><h2 id="end-to-end-workflow" tabindex="-1">End-to-End Workflow <a class="header-anchor" href="#end-to-end-workflow" aria-label="Permalink to &quot;End-to-End Workflow&quot;">​</a></h2><p>The workflow consists of three dedicated stages, isolated into modular packages:</p><ol><li><p><strong>Extraction (<code>packages/figma-plugin</code>)</strong>:</p><ul><li>Runs as a native Figma plugin.</li><li>Invokes <code>figma.loadAllPagesAsync()</code> to guarantee traversal of the entire document.</li><li>Extracts all local variables (color, spacing, numbers), paint styles, text styles, and component sets.</li><li>Dispatches a single structured payload to the TypeScript backend API (<code>apps/api</code>).</li></ul></li><li><p><strong>Deterministic Pre-Compiler &amp; Mitosis Authoring (<code>packages/mitosis-author</code>)</strong>:</p><ul><li>The TypeScript backend (<code>@supernova/api</code>) translates Figma Auto Layout geometry, <code>boundVariables</code>, and cleaned variant properties into a deterministic blueprint before invoking an OpenAI-compatible LLM endpoint.</li><li>Generates single-source Mitosis <code>.lite.tsx</code> JSX code using headless state management (<code>utils.ts</code>) and design tokens.</li><li>Normalizes Mitosis AST patterns and feeds compiler/render diagnostics back into the LLM prompt if initial compilation fails (stateful cross-attempt repair loop).</li></ul></li><li><p><strong>Multi-Target Compilation &amp; Quality Gate (<code>packages/mitosis-compiler</code>)</strong>:</p><ul><li>Directly invoked in-process by <code>@supernova/api</code> (zero subprocess overhead).</li><li>Compiles <code>.lite.tsx</code> components to 5 frontend frameworks with AST linting and SSR/DOM render verification: <ul><li><strong>React</strong> (<code>.tsx</code>)</li><li><strong>Svelte</strong> (<code>.svelte</code>)</li><li><strong>Vue 3</strong> Composition API (<code>.vue</code>)</li><li><strong>Vue 2</strong> Options API (<code>.vue</code>)</li><li><strong>Angular</strong> (<code>.ts</code>)</li></ul></li></ul></li><li><p><strong>Publishing &amp; Distribution</strong>:</p><ul><li><strong>Download ZIP</strong>: Download a packaged archive of all frameworks immediately from the plugin.</li><li><strong>GitHub Pull Request</strong>: Automatically branch, commit all generated code, and open a PR against your repository.</li></ul></li></ol>',5)])])}const m=o(n,[["render",l]]);export{g as __pageData,m as default};
